@@ -0,0 +1,53 @@
+import { Controller } from "@hotwired/stimulus"
+
+// This controller is responsible for creating and displaying the "Check NIK" button in the popup
+export default class extends Controller {
+  connect() {
+    // Find the NIK input field by its ID
+    this.nikInput = this.element.querySelector("#customer_nik")
+    if (!this.nikInput) return
+
+    // Store the original NIK value for comparison
+    this.originalNikValue = this.nikInput.value
+    
+    // Dynamically create the button
+    this.createCheckNikButton()
+
+    // Add a listener to monitor changes
+    this.nikInput.addEventListener("input", this.checkValue.bind(this))
+  }
+
+  createCheckNikButton() {
+    this.checkButton = document.createElement("button")
+    this.checkButton.type = "button"
+    
+    // START: Smaller and more aesthetic button style
+    this.checkButton.innerHTML = `
+      <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 mr-2" viewBox="0 0 20 20" fill="currentColor">
+        <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd" />
+      </svg>
+      Check NIK
+    `
+    this.checkButton.className = "flex items-center justify-center w-full text-sm bg-blue-100 text-blue-700 font-semibold py-2 rounded-full hover:bg-blue-200 mt-3 cursor-pointer"
+    // END: Smaller and more aesthetic button style
+
+    // KEY: Add data-action to call the existing 'nik-check' controller
+    this.checkButton.setAttribute("data-action", "click->nik-check#check")
+    
+    // Hide the button initially
+    this.checkButton.style.display = 'none'
+
+    // Insert the button into the page, right after the NIK input field
+    this.nikInput.parentElement.insertAdjacentElement('afterend', this.checkButton)
+  }
+
+  checkValue() {
+    // Show the button if the NIK value changes from the original
+    if (this.nikInput.value !== this.originalNikValue) {
+      this.checkButton.style.display = 'flex'
+    } else {
+      // Hide it again if the value returns to the original
+      this.checkButton.style.display = 'none'
+    }
+  }
+}
