import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["select"]

  connect() {
    console.log("LocationController initialized")
  }

  loadNext(event) {
    const source = event.target
    const currentLevel = source.dataset.level
    const nextLevel = this.getNextLevel(currentLevel)
    const nextSelect = this.selectTargets.find(el => el.dataset.level === nextLevel)

    if (!nextLevel || !nextSelect) {
      return
    }

    // clear downstream levels
    const clearFrom = this.selectTargets.findIndex(el => el.dataset.level === nextLevel)
    this.selectTargets.slice(clearFrom).forEach(el => this.clearSelect(el))

    const id = source.value
    if (!id) return

    // only postal use province id (tmp)
    if (nextLevel === "postal_code") {
      const provinceId = this.getProvinceId()
      this.loadPostalCodes(provinceId)
      return
    }

    // ! ADD JWT
    const endpoint = this.endpointFor(nextLevel, id)
    fetch(endpoint)
      .then(res => res.json())
      .then(data => this.populateSelect(nextSelect, data))
  }

  getProvinceId() {
    const provinceSelect = this.selectTargets.find(el => el.dataset.level === "province")
    return provinceSelect ? provinceSelect.value : null
  }

  loadPostalCodes(provinceId) {
    const postalSelect = this.selectTargets.find(el => el.dataset.level === "postal_code")
    if (!postalSelect || !provinceId) return

    this.clearSelect(postalSelect, "Pilih Kode Pos")

    const endpoint = `/portal/api/v1/postal_codes/${provinceId}`
    fetch(endpoint)
      .then(res => res.json())
      .then(data => this.populatePostalCodes(postalSelect, data))
  }

  endpointFor(level, id) {
    const endpoints = {
      regency: `/portal/api/v1/regencies/${id}`,
      district: `/portal/api/v1/districts/${id}`,
      village: `/portal/api/v1/villages/${id}`
    }
    return endpoints[level]
  }

  getNextLevel(current) {
    const order = ["province", "regency", "district", "village", "postal_code"]
    const index = order.indexOf(current)
    return index >= 0 && index < order.length - 1 ? order[index + 1] : null
  }

  clearSelect(select, placeholder = "Pilih") {
    select.innerHTML = `<option value="">${placeholder}</option>`
  }

  populateSelect(select, items) {
    items.forEach(item => {
      const opt = document.createElement("option")
      opt.value = item.code
      opt.textContent = item.name
      select.appendChild(opt)
    })
  }

  populatePostalCodes(select, codes) {
    codes.forEach(code => {
      const opt = document.createElement("option")
      opt.value = code
      opt.textContent = code
      select.appendChild(opt)
    })
    if (select.tomselect) {
      select.tomselect.sync();
    }
  }
}

