import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["submitButton"]

  check() {
    const csrfToken = document.querySelector("[name='csrf-token']").content
    const payload = {
      receiver_name: document.getElementById("receiver_name")?.value || "",
      receiver_no_handphone: document.getElementById("receiver_no_handphone")?.value || "",
      customer_nik: document.getElementById("customer_nik")?.value || "",
      customer_no_kk: document.getElementById("customer_no_kk")?.value || "",
      customer_birthdate: document.getElementById("customer_birthdate")?.value || ""
    }

    fetch("/portal/sales/nik_check", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-CSRF-Token": csrfToken
      },
      body: JSON.stringify(payload)
    }).then(response => {
      if (response.ok) {
        response.json().then(data => {
          if (data.success) {
            alert("Customer sukses dilakukan pengecekan awal, silahkan untuk melanjutkan order")
            if (this.isFeatureEnabled()) {
              this.enableSubmitButton()
            }
          } else if (!data.success && data.message) {
            alert(data.message)
            if (this.isFeatureEnabled()) {
              this.disableSubmitButton()
            }
          }
        })
      } else {
        response.json().then(data => {
          alert("Gagal melakukan cek NIK Customer: \n\n" + data.message)
          if (this.isFeatureEnabled()) {
            this.disableSubmitButton()
          }
        })
      }
    }).catch(() => {
      alert("Gagal melakukan cek NIK customer")
      if (this.isFeatureEnabled()) {
        this.disableSubmitButton()
      }
    })
  }

  enableSubmitButton() {
    this.submitButtonTarget.disabled = false
    this.submitButtonTarget.classList.remove("bg-gray-300", "cursor-not-allowed")
    this.submitButtonTarget.classList.add("bg-blue-600", "hover:bg-blue-500", "cursor-pointer")
  }

  disableSubmitButton() {
    this.submitButtonTarget.disabled = true
    this.submitButtonTarget.classList.remove("bg-gray-500", "hover:bg-gray-600", "cursor-pointer")
    this.submitButtonTarget.classList.add("bg-gray-300", "cursor-not-allowed")
  }

  isFeatureEnabled() {
    return this.hasSubmitButtonTarget;
  }
}

