    "suggested_code": "waitForOption(select, value, maxAttempts = 50) {
  return new Promise((resolve, reject) => {
    let attempts = 0;

    const checkOption = () => {
      attempts++;

      // Check if we've exceeded max attempts (5 seconds with 100ms intervals)
      if (attempts > maxAttempts) {
        console.error(`Timeout waiting for option ${value} in select`);
        reject(new Error(`Option ${value} not found after ${maxAttempts * 100}ms`));
        return;
      }

      // Check if select element still exists in DOM
      if (!document.contains(select)) {
        reject(new Error('Select element removed from DOM'));
        return;
      }

      const option = select.querySelector(`option[value="${value}"]`);
      if (option) {
        resolve(option);
      } else {
        setTimeout(checkOption, 100);
      }
    };

    checkOption();
  });
}

// Better alternative: Use MutationObserver
waitForOption(select, value, timeout = 5000) {
  return new Promise((resolve, reject) => {
    const option = select.querySelector(`option[value="${value}"]`);
    if (option) {
      resolve(option);
      return;
    }

    const observer = new MutationObserver((mutations) => {
      const option = select.querySelector(`option[value="${value}"]`);
      if (option) {
        observer.disconnect();
        resolve(option);
      }
    });

    observer.observe(select, { childList: true, subtree: true });

    // Timeout fallback
    setTimeout(() => {
      observer.disconnect();
      reject(new Error(`Option ${value} not found after ${timeout}ms`));
    }, timeout);
  });
}",
