    "suggested_code": "// Better alternative: Use MutationObserver
waitForOption(select, value, timeout = 5000) {
  return new Promise((resolve, reject) => {
    const option = select.querySelector(`option[value="${value}"]`);
    if (option) {
      resolve(option);
      return;
    }

    const observer = new MutationObserver((mutations) => {
      const option = select.querySelector(`option[value="${value}"]`);
      if (option) {
        observer.disconnect();
        resolve(option);
